practice.solution:
public class Main {
    public static void main(String[] args) {
        int years = 100;
        int secondsPerYear = 365 * 24 * 60 * 60;
        System.out.println("Seconds per year: " + secondsPerYear);

        long wrong = years * secondsPerYear;
        long right = (long) years * secondsPerYear;
        System.out.println("Int math: " + wrong);
        System.out.println("Long math: " + right);
        System.out.println("Most years in an int: " + Integer.MAX_VALUE / secondsPerYear);
    }
}

