public class Main {
    public static void main(String[] args) {
        double up = Double.POSITIVE_INFINITY;
        double down = Double.NEGATIVE_INFINITY;
        System.out.println("up: " + up);
        System.out.println("down: " + down);
        int fewest = Integer.MAX_VALUE;
        System.out.println("fewest: " + fewest);

        double ratio = 1.0 / 0;
        double unknown = 0.0 / 0;
        System.out.println("1.0 / 0 = " + ratio);
        System.out.println("0.0 / 0 = " + unknown);
        System.out.println("ratio infinite? " + Double.isInfinite(ratio));
        System.out.println("unknown NaN? " + Double.isNaN(unknown));
        System.out.println("unknown infinite? " + Double.isInfinite(unknown));
        System.out.println("tiny: " + Double.MIN_VALUE);
    }
}

