public class Main {
    public static void main(String[] args) {
        double bestTime = Double.POSITIVE_INFINITY;
        double highestReading = Double.NEGATIVE_INFINITY;
        int smallestCount = Integer.MAX_VALUE;
        System.out.println("Best time: " + bestTime);
        System.out.println("Highest reading: " + highestReading);
        System.out.println("Smallest count: " + smallestCount);

        double gap = bestTime - bestTime;
        System.out.println("Infinity - Infinity = " + gap);
        System.out.println("Is NaN: " + Double.isNaN(gap));
        System.out.println("Is infinite: " + Double.isInfinite(bestTime));
    }
}

